'use strict'

// Applies model supplied patch operations atomically per task. If any single
// operation is impossible (missing anchor, ambiguous anchor, file already
// exists), NOTHING is written - the task fails cleanly and the error text goes
// back to the model as a repair hint.

const fs = require('fs')
const path = require('path')
const { ensureDir, dateStamp } = require('../util')

const MAX_FILES_PER_TASK = 10
const MAX_FILE_CHARS = 400000
// Generated by the factory after every stage: a patch would be silently lost.
const PROTECTED_PATHS = ['docs/ssot.html']

function normalizeOperation(rawOperation) {
  if (!rawOperation || typeof rawOperation !== 'object') return null
  // Models use several names for the replacement text; accept them all so a
  // naming difference never costs a whole task attempt.
  const contentSource = rawOperation.content !== undefined ? rawOperation.content
    : rawOperation.replace !== undefined ? rawOperation.replace
      : rawOperation.text !== undefined ? rawOperation.text
        : ''
  const operation = {
    op: String(rawOperation.op || rawOperation.operation || '').toLowerCase().trim(),
    file: String(rawOperation.file || rawOperation.path || '').replace(/\\/g, '/').replace(/^\.?\//, ''),
    content: String(contentSource === undefined || contentSource === null ? '' : contentSource),
    find: rawOperation.find !== undefined ? String(rawOperation.find) : ''
  }
  if (!operation.op) {
    if (operation.content && !operation.find) operation.op = 'create'
    else if (operation.content && operation.find) operation.op = 'replace'
  }
  if (operation.op === 'write' || operation.op === 'overwrite') operation.op = 'create'
  if (operation.op === 'insert') operation.op = 'append'
  return operation
}

function countOccurrences(haystack, needle) {
  if (!needle) return 0
  let count = 0
  let index = haystack.indexOf(needle)
  while (index !== -1) {
    count += 1
    index = haystack.indexOf(needle, index + needle.length)
  }
  return count
}

function applyOps(workspace, rawOperations, options) {
  const settings = options || {}
  const operations = (Array.isArray(rawOperations) ? rawOperations : [])
    .map(normalizeOperation)
    .filter(Boolean)

  const problems = []
  if (!operations.length) {
    return { ok: false, problems: [{ file: '', message: 'The answer contained no operations.' }], changed: [] }
  }
  if (operations.length > MAX_FILES_PER_TASK) {
    return {
      ok: false,
      problems: [{ file: '', message: 'Too many operations in one task (' + operations.length + '). Split the task into smaller tasks (limit ' + MAX_FILES_PER_TASK + ').' }],
      changed: []
    }
  }

  const staged = new Map()
  const originals = new Map()

  for (const operation of operations) {
    if (!operation.file) {
      problems.push({ file: '', message: 'An operation is missing the "file" field.' })
      continue
    }
    if (operation.op !== 'delete' && !operation.content) {
      problems.push({ file: operation.file, message: 'The "' + operation.op + '" operation has empty content.' })
      continue
    }
    if (operation.content.length > MAX_FILE_CHARS) {
      problems.push({ file: operation.file, message: 'Content is too large (' + operation.content.length + ' chars, limit ' + MAX_FILE_CHARS + ').' })
      continue
    }

    let absolutePath
    try {
      absolutePath = workspace.resolveInside(operation.file)
    } catch (error) {
      problems.push({ file: operation.file, message: error.message })
      continue
    }

    const relativePath = workspace.relativeOf(absolutePath)
    const currentlyKnown = staged.has(relativePath)
      ? staged.get(relativePath)
      : (fs.existsSync(absolutePath) ? fs.readFileSync(absolutePath, 'utf8') : null)
    if (!originals.has(relativePath)) originals.set(relativePath, currentlyKnown)

    if (PROTECTED_PATHS.includes(relativePath)) {
      problems.push({
        file: relativePath,
        message: 'This file is generated by the factory and cannot be changed by a task.'
      })
      continue
    }

    if (operation.op === 'create') {
      if (currentlyKnown !== null) {
        problems.push({
          file: relativePath,
          message: 'The file already exists. Use "replace" with a unique "find" anchor, or "append", instead of "create".'
        })
        continue
      }
      staged.set(relativePath, operation.content)
      continue
    }

    if (operation.op === 'replace') {
      if (currentlyKnown === null) {
        problems.push({ file: relativePath, message: 'Cannot replace inside a file that does not exist. Use "create".' })
        continue
      }
      if (!operation.find) {
        problems.push({ file: relativePath, message: 'A "replace" operation needs a "find" anchor.' })
        continue
      }
      const matches = countOccurrences(currentlyKnown, operation.find)
      if (matches === 0) {
        problems.push({
          file: relativePath,
          message: 'The "find" anchor was not found. Use text that exists in the file exactly as written (whitespace included).'
        })
        continue
      }
      if (matches > 1) {
        problems.push({
          file: relativePath,
          message: 'The "find" anchor matches ' + matches + ' times. Include more surrounding lines so it matches exactly once.'
        })
        continue
      }
      staged.set(relativePath, currentlyKnown.replace(operation.find, operation.content))
      continue
    }

    if (operation.op === 'append') {
      staged.set(relativePath, (currentlyKnown === null ? '' : currentlyKnown) + operation.content)
      continue
    }

    if (operation.op === 'delete') {
      if (settings.allowDelete !== true) {
        problems.push({
          file: relativePath,
          message: 'Deleting files is disabled. Replace the content instead, or ask the operator to enable tool.allowDelete.'
        })
        continue
      }
      if (currentlyKnown === null) {
        problems.push({ file: relativePath, message: 'Cannot delete a file that does not exist.' })
        continue
      }
      staged.set(relativePath, null)
      continue
    }

    problems.push({ file: relativePath, message: 'Unknown operation "' + operation.op + '". Use create, replace, append or delete.' })
  }

  if (problems.length) return { ok: false, problems, changed: [] }

  // Backups first, then write everything.
  const backupDirectory = settings.backupDirectory
    ? path.join(settings.backupDirectory, dateStamp() + '-' + Math.random().toString(36).slice(2, 6))
    : null
  if (backupDirectory) {
    for (const [relativePath, originalText] of originals.entries()) {
      if (originalText === null) continue
      const backupPath = path.join(backupDirectory, relativePath)
      ensureDir(path.dirname(backupPath))
      fs.writeFileSync(backupPath, originalText, 'utf8')
    }
  }

  const changed = []
  try {
    for (const [relativePath, nextText] of staged.entries()) {
      const absolutePath = workspace.resolveInside(relativePath)
      if (nextText === null) {
        if (fs.existsSync(absolutePath)) fs.unlinkSync(absolutePath)
      } else {
        ensureDir(path.dirname(absolutePath))
        fs.writeFileSync(absolutePath, nextText, 'utf8')
      }
      changed.push({
        file: relativePath,
        before: originals.get(relativePath),
        after: nextText
      })
    }
  } catch (writeError) {
    // Roll back whatever already landed.
    for (const [relativePath, originalText] of originals.entries()) {
      try {
        const absolutePath = workspace.resolveInside(relativePath)
        if (originalText === null) {
          if (fs.existsSync(absolutePath)) fs.unlinkSync(absolutePath)
        } else {
          fs.writeFileSync(absolutePath, originalText, 'utf8')
        }
      } catch (_rollbackError) {
        // best effort
      }
    }
    return {
      ok: false,
      problems: [{ file: '', message: 'Writing failed and was rolled back: ' + writeError.message }],
      changed: []
    }
  }

  return { ok: true, problems: [], changed, backupDirectory }
}

module.exports = { applyOps, normalizeOperation, countOccurrences, PROTECTED_PATHS }
